import React, { useRef, useState } from 'react';
import emailjs from '@emailjs/browser';
import { motion } from 'framer-motion';
import { Mail, Linkedin, Github, Phone, Send, CheckCircle, Sparkles } from 'lucide-react';

const Contact = () => {
  const form = useRef();
  const [isSent, setIsSent] = useState(false);

  const sendEmail = (e) => {
    e.preventDefault();
    // Use your EmailJS IDs here
    emailjs.sendForm('YOUR_SERVICE_ID', 'YOUR_TEMPLATE_ID', form.current, 'YOUR_PUBLIC_KEY')
      .then(() => {
          setIsSent(true);
          form.current.reset();
          setTimeout(() => setIsSent(false), 5000);
      }, (error) => {
          console.error(error.text);
      });
  };

  return (
    <section id="contact" className="py-24 px-10 bg-[#0a0a0a] relative overflow-hidden text-white">
      {/* Background Decorative Glows */}
      <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-blue-600/10 rounded-full blur-[120px] -z-0" />
      <div className="absolute bottom-0 left-0 w-[300px] h-[300px] bg-blue-500/10 rounded-full blur-[100px] -z-0" />

      <div className="container mx-auto max-w-6xl relative z-10">
        <div className="flex flex-col md:flex-row gap-16 items-center">

          {/* Left Side: Creative Branding */}
          <motion.div 
            initial={{ opacity: 0, x: -30 }}
            whileInView={{ opacity: 1, x: 0 }}
            className="md:w-1/2"
          >
            <div className="inline-flex items-center gap-2 px-4 py-2 rounded-full bg-blue-500/10 border border-blue-500/20 text-blue-400 text-sm font-bold mb-6">
              <Sparkles size={16} /> Available for Internships
            </div>
            <h2 className="text-6xl font-black tracking-tighter leading-none mb-6">
              READY TO <br /> <span className="text-blue-500 underline decoration-blue-500/30">COLLABORATE?</span>
            </h2>
            <p className="text-gray-400 text-lg max-w-md mb-10 leading-relaxed">
              [cite_start]Based in Dausa, Rajasthan[cite: 52, 53]. I'm currently looking for Software Intern roles where I can apply my 
              [cite_start]skills in C++, Python, and React[cite: 5, 7, 51].
            </p>

            <div className="space-y-6">
              <div className="flex items-center gap-4 group">
                <div className="p-4 bg-white/5 rounded-2xl group-hover:bg-blue-600 transition-colors">
                  <Mail size={24} className="group-hover:text-white" />
                </div>
                [cite_start]<p className="font-bold text-xl">agrawalnaitik508@gmail.com [cite: 6]</p>
              </div>
              <div className="flex items-center gap-4 group">
                <div className="p-4 bg-white/5 rounded-2xl group-hover:bg-blue-600 transition-colors">
                  <Phone size={24} />
                </div>
                [cite_start]<p className="font-bold text-xl">+91-7878509131 [cite: 6]</p>
              </div>
            </div>
          </motion.div>

          {/* Right Side: Glassmorphic Form */}
          <motion.div 
            initial={{ opacity: 0, scale: 0.95 }}
            whileInView={{ opacity: 1, scale: 1 }}
            className="md:w-1/2 w-full"
          >
            <div className="backdrop-blur-xl bg-white/5 border border-white/10 p-8 md:p-12 rounded-[2.5rem] shadow-2xl">
              {isSent ? (
                <div className="text-center py-20">
                  <CheckCircle size={80} className="text-blue-500 mx-auto mb-6" />
                  <h3 className="text-3xl font-bold">Message Sent!</h3>
                  <p className="text-gray-400 mt-2">I'll get back to you shortly, Naitik.</p>
                </div>
              ) : (
                <form ref={form} onSubmit={sendEmail} className="space-y-6">
                  <div className="grid grid-cols-2 gap-4">
                    <input name="first_name" required placeholder="First Name" className="w-full p-4 bg-white/5 rounded-2xl border border-white/10 focus:border-blue-500 outline-none transition-all placeholder:text-gray-600" />
                    <input name="last_name" required placeholder="Last Name" className="w-full p-4 bg-white/5 rounded-2xl border border-white/10 focus:border-blue-500 outline-none transition-all placeholder:text-gray-600" />
                  </div>
                  <input name="email" required type="email" placeholder="Email Address" className="w-full p-4 bg-white/5 rounded-2xl border border-white/10 focus:border-blue-500 outline-none transition-all placeholder:text-gray-600" />
                  <textarea name="message" required rows="4" placeholder="Your Message" className="w-full p-4 bg-white/5 rounded-2xl border border-white/10 focus:border-blue-500 outline-none transition-all resize-none placeholder:text-gray-600"></textarea>

                  <button type="submit" className="w-full bg-blue-600 text-white py-5 rounded-2xl font-black uppercase tracking-widest hover:bg-blue-500 hover:shadow-[0_0_30px_rgba(37,99,235,0.4)] transition-all flex items-center justify-center gap-3">
                    Submit Message <Send size={20} />
                  </button>
                </form>
              )}
            </div>
          </motion.div>
        </div>
      </div>
    </section>
  );
};

export default Contact;
